        );

        var result = mod.action({
            inputFolderPath: 'input/PROJ-123',
            jobParams: { inputFolderPath: 'input/PROJ-123', customParams: {} }
        });

        assert.equal(result.success, true, 'action succeeded — got: ' + JSON.stringify(result));
